interface MetricVector {
  metric: string;
  labels: Record<string, string>;
  value: number;
}

class PromQlEngineSimulator {
  executeManyToOneJoin(
    leftVector: MetricVector[],
    rightVector: MetricVector[],
    joinLabels: string[]
  ): Array<{ metric: string; pod: string; cluster: string; memoryBytes: number; nodeCapacityBytes: number; memoryRatioPct: number }> {
    const rightMap = new Map<string, MetricVector>();
    for (const r of rightVector) {
      const key = joinLabels.map(k => r.labels[k] || '').join(':');
      rightMap.set(key, r);
    }

    const results: Array<{ metric: string; pod: string; cluster: string; memoryBytes: number; nodeCapacityBytes: number; memoryRatioPct: number }> = [];
    for (const l of leftVector) {
      const key = joinLabels.map(k => l.labels[k] || '').join(':');
      const matched = rightMap.get(key);
      if (matched && matched.value > 0) {
        const ratio = (l.value / matched.value) * 100;
        results.push({
          metric: l.metric,
          pod: l.labels['pod'] || '',
          cluster: l.labels['cluster'] || '',
          memoryBytes: l.value,
          nodeCapacityBytes: matched.value,
          memoryRatioPct: Math.round(ratio)
        });
      } 
    }
    return results;
  }
}

