}

class W3cTraceContextPropagator {
  parseTraceParent(headerValue: string): TraceContext {
    const parts = headerValue.split('-');
    if (parts.length !== 4) {
      throw new Error(`Invalid W3C traceparent header: ${headerValue}`);
    }

    const [version, traceId, parentSpanId, traceFlags] = parts;
    const flagsNum = parseInt(traceFlags, 16);
    const isSampled = (flagsNum & 0x01) === 0x01;

    return {
      version,
      traceId,
      parentSpanId,
      traceFlags,
      isSampled
    };
  }

  injectTraceParent(ctx: TraceContext, nextSpanId: string): string {
    return `${ctx.version}-${ctx.traceId}-${nextSpanId}-${ctx.traceFlags}`;
  }
}

