class OpenTelemetryBatchProcessorSimulator {
  private spanQueue: SpanRecord[] = [];
  private maxQueueSize: number;
  private maxBatchSize: number;
  private droppedSpansCount = 0;

  constructor(maxQueueSize: number = 2048, maxBatchSize: number = 64) {
    this.maxQueueSize = maxQueueSize;
    this.maxBatchSize = maxBatchSize;
  }

  onEnd(span: SpanRecord): void {
    if (this.spanQueue.length >= this.maxQueueSize) {
      this.droppedSpansCount++;
      return;
    }
    this.spanQueue.push(span);
  }

  flushBatch(): { spansExported: number; remainingQueue: number; dropped: number; queueUtilizationPct: number } {
    const batch = this.spanQueue.splice(0, this.maxBatchSize);
    const util = Math.round((this.spanQueue.length / this.maxQueueSize) * 100);

    return {
      spansExported: batch.length,
      remainingQueue: this.spanQueue.length,
      dropped: this.droppedSpansCount,
      queueUtilizationPct: util
    };
  }
}

