class TailBasedSamplingEngine {
  evaluateTrace(trace: TraceEvaluation): { sampled: boolean; reason: string } {
    if (trace.hasError) {
      return { sampled: true, reason: 'ERROR_RETAINED_100PCT' };
    }

    if (trace.durationMs > 500) {
      return { sampled: true, reason: 'HIGH_LATENCY_RETAINED' };
    }

    const hash = parseInt(trace.traceId.slice(-2), 16);
    if (hash % 100 === 0) {
      return { sampled: true, reason: 'PROBABILISTIC_BASELINE_1PCT' };
    }

    return { sampled: false, reason: 'DISCARDED_NORMAL_TRACE' };
  }
}

