interface CriLogLine {
  timestamp: string;
  stream: 'stdout' | 'stderr';
  flag: 'F' | 'P';
  payload: string;
}

class CriLogStreamParser {
  parseLogLine(rawLine: string): CriLogLine {
    const match = rawLine.match(/^(\S+)\s+(stdout|stderr)\s+(F|P)\s+(.*)$/);
    if (!match) {
      throw new Error(`Invalid CRI log line format: ${rawLine}`);
    }
    return {
      timestamp: match[1],
      stream: match[2] as 'stdout' | 'stderr',
      flag: match[3] as 'F' | 'P',
      payload: match[4]
    };
  }

  extractJsonFields(log: CriLogLine): { fieldCount: number; isValidJson: boolean } {
    try {
      const parsed = JSON.parse(log.payload);
      return {
        fieldCount: Object.keys(parsed).length,
        isValidJson: true
      };
    } catch {
      return { fieldCount: 0, isValidJson: false };
    }
  }
}

