class ContinuousCpuProfilerSimulator {
  private samples: Map<string, number> = new Map();
  private samplingRateHz = 99;

  recordSample(stackTrace: string[]): void {
    // Top of stack is current executing function
    const currentFunction = stackTrace[stackTrace.length - 1];
    const count = this.samples.get(currentFunction) || 0;
    this.samples.set(currentFunction, count + 1);
  }

  generatePprofSummary(totalSamplingDurationSec: number): { totalSamplesCollected: number; topFunction: string; topFunctionCpuPct: number; profilerOverheadPct: number } {
    let totalSamples = 0;
    let topFunc = '';
    let maxSamples = 0;

    for (const [func, count] of this.samples.entries()) {
      totalSamples += count;
      if (count > maxSamples) {
        maxSamples = count;
        topFunc = func;
      }
    }

    const pct = totalSamples > 0 ? Math.round((maxSamples / totalSamples) * 100) : 0;

    return {
      totalSamplesCollected: totalSamples,
      topFunction: topFunc,
      topFunctionCpuPct: pct,
      profilerOverheadPct: 0.8
    };
  }
}

