      maxDepth = Math.max(maxDepth, frames.length);

      for (const frame of frames) {
        const current = functionWeights.get(frame) || 0;
        functionWeights.set(frame, current + stack.sampleCount);
      }
    }

    let widest = '';
    let maxWeight = 0;
    for (const [frame, weight] of functionWeights.entries()) {
      if (frame !== 'main' && frame !== 'router.ServeHTTP' && weight > maxWeight) {
        maxWeight = weight;
        widest = frame;
      }
    }

    const pct = total > 0 ? Math.round((maxWeight / total) * 100) : 0;

    return {
      totalSamples: total,
      widestFunction: widest,
      widestWidthPct: pct,
      stackDepth: maxDepth
    };
  }
}

