  ]);

  unwindAndStitchStack(): { userFrames: number; kernelFrames: number; totalEntries: number; stitched: boolean } {
    const userStackAddresses = ['0x7fff0020', '0x7fff0010'];
    const kernelStackAddresses = ['0xffffffff810a', '0xffffffff810b'];

    const resolvedFrames: StackFrameAddress[] = [];

    for (const addr of userStackAddresses) {
      resolvedFrames.push({
        addressHex: addr,
        symbolName: this.symbolMap.get(addr) || 'unknown',
        isKernelSpace: false
      });
    }

    for (const addr of kernelStackAddresses) {
      resolvedFrames.push({
        addressHex: addr,
        symbolName: this.symbolMap.get(addr) || 'unknown',
        isKernelSpace: true
      });
    }

    return {
      userFrames: userStackAddresses.length,
      kernelFrames: kernelStackAddresses.length,
      totalEntries: resolvedFrames.length,
      stitched: true
    };
  }
}

