interface SloMetrics {
  service: string;
  targetAvailabilityPct: number;
  totalRequests: number;
  failedRequests: number;
}

class SloBudgetCalculator {
  calculateErrorBudget(metrics: SloMetrics): { availabilityPct: number; remainingBudgetPct: number; steadyStateMaintained: boolean } {
    const successRequests = metrics.totalRequests - metrics.failedRequests;
    const actualAvailability = (successRequests / metrics.totalRequests) * 100;
    const allowedErrorRate = 100 - metrics.targetAvailabilityPct;
    const actualErrorRate = (metrics.failedRequests / metrics.totalRequests) * 100;
    const remainingBudgetPct = Math.max(0, Math.round(((allowedErrorRate - actualErrorRate) / allowedErrorRate) * 100));

    return {
      availabilityPct: parseFloat(actualAvailability.toFixed(3)),
      remainingBudgetPct,
      steadyStateMaintained: actualAvailability >= metrics.targetAvailabilityPct
    };
  }
}

